@apply_rules(verify_arg('min_commission').is_instance((int, float, None.__class__)), verify_arg('stock_commission').is_instance((int, float, None.__class__)), verify_arg('stock_tax').is_instance((int, float, None.__class__)))
def set_stock_fees(min_commission=5, stock_commission=0.0008, stock_tax=0.001):
    if min_commission is None or min_commission < 0 or min_commission > 10:
        raise IQInvalidArgument('设置股票最小佣金出错，最小佣金范围为[0, 10]')
    elif stock_commission is None or stock_commission < 0 or stock_commission > 0.003:
        raise IQInvalidArgument('设置股票佣金费率出错，费率范围为[0, 0.003]')
    elif stock_tax is None or stock_tax < 0 or stock_tax > 0.01:
        raise IQInvalidArgument('设置股票印花税出错，税率范围为[0, 0.01]')
    else:
        commission = Engine.instance().get_commission(AssetType.STOCK.value)
        if commission:
            commission.set_commission(stock_commission, min_commission)
    tax = Engine.instance().get_tax()
    if tax:
        tax.set_tax(stock_tax)
        return None
@ExecutionContext.enforce_phase(ExecutionPhase.INITIALIZE)
@apply_rules(verify_arg('open_commission').is_number(), verify_arg('close_commission').is_number(), verify_arg('close_today_commission').is_number(), verify_arg('trade_code').is_instance(str), verify_arg('type').is_instance(str))
def set_future_fees(open_commission, close_commission, close_today_commission, trade_code, type):
    commission = Engine.instance().get_commission(AssetType.FUTURE.value)
    if type == CommissionType.BY_MONEY.value:
        if open_commission < 0 or open_commission > 0.001:
            raise IQInvalidArgument('设置期货开仓费用出错，BY_MONEY开仓费用范围为[0, 0.001]')
        elif close_commission < 0 or close_commission > 0.001:
            raise IQInvalidArgument('设置期货平昨仓费用出错，BY_MONEY平昨仓费用范围为[0, 0.001]')
        elif close_today_commission < 0 or close_today_commission > 0.001:
            raise IQInvalidArgument('设置期货平今仓费用出错，BY_MONEY平今仓费用范围为[0, 0.001]')
        else:
            commission.set_commission(open_commission, close_commission, close_today_commission, trade_code, CommissionType.BY_MONEY)
    elif type == CommissionType.BY_VOLUME.value:
        if open_commission < 0 or open_commission > 100:
            raise IQInvalidArgument('设置期货开仓费用出错，BY_VOLUME开仓费用范围为[0, 100]')
        elif close_commission < 0 or close_commission > 100:
            raise IQInvalidArgument('设置期货平昨仓费用出错，BY_VOLUME平昨仓费用范围为[0, 100]')
        elif close_today_commission < 0 or close_today_commission > 100:
            raise IQInvalidArgument('设置期货平今仓费用出错，BY_VOLUME平今仓费用范围为[0, 100]')
        else:
            commission.set_commission(open_commission, close_commission, close_today_commission, trade_code, CommissionType.BY_VOLUME)
    else:
        raise IQInvalidArgument("set_future_fees的type类型无效，仅支持'BY_MONEY'或'BY_VOLUME'")
